import{_ as s,C as e,o as n,c as d,j as a,a as h,E as r,a2 as o}from"./chunks/framework.B-bxTAy7.js";const m=JSON.parse('{"title":"嵌入式开发 · 课程主页","description":"以 STM32 / ARM Cortex-M 为载体的嵌入式课程：开发环境、寄存器思维、时钟树、GPIO、中断、定时器 PWM、UART、SPI/I²C、ADC/DMA、FreeRTOS、低功耗与舵机控制。","frontmatter":{"title":"嵌入式开发 · 课程主页","description":"以 STM32 / ARM Cortex-M 为载体的嵌入式课程：开发环境、寄存器思维、时钟树、GPIO、中断、定时器 PWM、UART、SPI/I²C、ADC/DMA、FreeRTOS、低功耗与舵机控制。"},"headers":[],"relativePath":"embedded/index.md","filePath":"embedded/index.md","lastUpdated":1792603101000}'),g={name:"embedded/index.md"};function p(c,t,C,P,u,S){const l=e("Meta"),i=e("CourseRoadmap");return n(),d("div",null,[t[0]||(t[0]=a("h1",{id:"嵌入式开发",tabindex:"-1"},[h("嵌入式开发 "),a("a",{class:"header-anchor",href:"#嵌入式开发","aria-label":'Permalink to "嵌入式开发"'},"​")],-1)),r(l,{time:"8 min",level:"指南",note:"从「会算电路」到「让芯片干活」：MCU 架构、外设、RTOS 一条线打通"}),t[1]||(t[1]=o('<p>前面三门课让你<strong>看懂</strong>电路与信号：电工学讲连续量，数电讲逻辑状态，模电讲模拟器件的微观机理。但它们停在了原理——你还没真的让一个芯片去<strong>读一个按键、发一串串口、控一台电机</strong>。</p><p>嵌入式开发就是这最后一步：<strong>把物理世界和数字世界连起来，让 MCU 按你的程序跑起来</strong>。本课程以 <strong>STM32（ARM Cortex-M 内核）</strong> 为载体——工业与教学里最主流的 32 位单片机，资料多、生态全；但讲的概念（时钟树、GPIO、中断、定时器、UART/SPI/I²C、ADC/DMA、RTOS）是<strong>所有 MCU 通用的</strong>，换到 ESP32、GD32、NXP 也只差寄存器名字。</p><h2 id="学完能得到什么" tabindex="-1">学完能得到什么 <a class="header-anchor" href="#学完能得到什么" aria-label="Permalink to &quot;学完能得到什么&quot;">​</a></h2><ul><li>从零建一个 STM32 工程，独立完成编译、下载、断点调试与串口打印；</li><li>读懂时钟树，算清 PLL 与 AHB/APB 分频，知道「外设为什么不工作」的第一嫌疑是没开时钟；</li><li>把 GPIO 四种模式、上下拉、开漏/推挽与实际接法对应起来，写出不抖的按键检测；</li><li>配置中断与 NVIC 优先级，解释抢占、子优先级、咬尾与晚到；</li><li>用定时器做 PWM、输入捕获与编码器测速，用 UART/SPI/I²C 与传感器通信；</li><li>用 ADC + DMA 采数据、做滤波；用 FreeRTOS 把裸机 super-loop 拆成任务；</li><li>做一次完整的低功耗设计，知道 Sleep/Stop/Standby 的代价与唤醒源；</li><li>用定时器 PWM 驱动一个真实执行器（舵机），算清 PSC/ARR/CCR，并且知道抖动与烧板大多出在供电和地上。</li></ul><h2 id="章节路线" tabindex="-1">章节路线 <a class="header-anchor" href="#章节路线" aria-label="Permalink to &quot;章节路线&quot;">​</a></h2>',5)),r(i,{course:"embedded"}),t[2]||(t[2]=o('<h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>顺序</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>速通</strong>（约 5 h）</td><td>01 → 02 → 04 → 05 → 06 → 07 → 08</td><td>只求能点灯、能串口、能中断</td></tr><tr><td><strong>系统</strong>（约 10 h）</td><td>01 → 13 顺序读，每个外设都上手接一次</td><td>要独立做项目</td></tr><tr><td><strong>补强</strong></td><td>时钟算错回 04，中断乱了回 06，通信不通回 08/09，舵机抖/角度不准回 13</td><td>已经在写但常踩坑</td></tr><tr><td><strong>动手派</strong>（约 4 h）</td><td>07 → 13 → 10 → 11</td><td>手上有舵机/传感器，想先做出能动的实物</td></tr></tbody></table><h3 id="关于第-13-章" tabindex="-1">关于第 13 章 <a class="header-anchor" href="#关于第-13-章" aria-label="Permalink to &quot;关于第 13 章&quot;">​</a></h3><p><strong>13 · 舵机控制：从 PWM 脉宽到角度</strong> 是本课的「第一个真正动起来的项目」：它把 07 章的定时器 PWM 落到一个具体器件上，并且是<strong>唯一一节把电源与接线当成主线讲</strong>的章节——舵机堵转电流是开发板 LDO 的十倍量级，「代码全对但一直抖/一直复位」的根因几乎都在这里。建议在学完 07 章后立刻读，配合一个 SG90 和一块外部 5 V 电源动手；如果要扩展成多路机械臂，再去读 11 章用 RTOS 做任务调度。</p><p>如果只想要<strong>结论清单</strong>：50 Hz、0.5–2.5 ms、1.5 ms 中位、72 MHz → PSC 71 / ARR 19999 / CCR 500~2500、84 MHz → PSC 83；舵机必须独立 5 V 供电且与 STM32 共地。</p><h2 id="和前三门课的关系-以及两种读法" tabindex="-1">和前三门课的关系（以及两种读法） <a class="header-anchor" href="#和前三门课的关系-以及两种读法" aria-label="Permalink to &quot;和前三门课的关系（以及两种读法）&quot;">​</a></h2><ul><li><strong>电工学</strong>：推挽/开漏输出、上下拉电阻、电平标准（TTL/CMOS）——在 GPIO 章直接复用，不用重学；13 章的电源估算本质上是一次直流电源与线路压降的计算——堵转电流 × 回路电阻 = 你实际送到舵机上的电压，这和<a href="./../ee/02-methods/equivalent">电工学 · 等效电路</a>里的戴维南模型是同一件事。</li><li><strong>数字电路</strong>：寄存器、时序、总线仲裁（三态/开漏总线）——UART/SPI/I²C 的帧和波形，本质是数电时序的工业版。</li><li><strong>模拟电子</strong>：ADC 把模拟电压量化成数字码、运放做信号调理、PWM 滤波出模拟量——模电的「模拟↔数字接口」在这里闭环；13 章里舵机内部的「电位器反馈 + 误差驱动电机」则是这套模拟接口在机电系统里的原型。</li></ul><p>两种读法：</p><ul><li><strong>有电路基础</strong>：跳过「为什么推挽」「为什么上拉」这类铺垫，直奔「寄存器怎么配、HAL 怎么用、坑在哪」。</li><li><strong>零基础直接来</strong>：每章都从「这个器件/概念在物理上是什么」讲起，依赖的电路知识用前置知识胶囊兜底。</li></ul><h2 id="暂不涉及的内容" tabindex="-1">暂不涉及的内容 <a class="header-anchor" href="#暂不涉及的内容" aria-label="Permalink to &quot;暂不涉及的内容&quot;">​</a></h2><p>以下不是不学，而是明确<strong>不在这一版课程里</strong>：CAN/LIN 总线、USB、以太网、嵌入式 Linux（Cortex-A）、LVGL 图形界面、OTA/固件安全、MISRA-C 规范；舵机只讲标准模拟舵机（PWM 接口），不讲串行总线数字舵机（RS485/CAN 舵机）的协议层。先把手脚（MCU 外设 + RTOS + 一个能动的执行器）练熟，再选赛道深挖。</p><h2 id="相关实验与专题" tabindex="-1">相关实验与专题 <a class="header-anchor" href="#相关实验与专题" aria-label="Permalink to &quot;相关实验与专题&quot;">​</a></h2><p>这门课是最容易「代码全对、现象全错」的，所以它和实验板块、项目专题的绑定最紧：</p><ul><li><strong>双轴舵机云台</strong>（<a href="./../topics/servo-gimbal">/topics/servo-gimbal</a>）：第 13 章把一个舵机讲透，云台则要同时驱动两个、还要把坐标映射成角度。本课里「独立 5 V 供电 + 共地」那一条纪律，到云台上会被放大成抖动与复位问题，90% 的故障都出在这里。</li><li><strong>示波器</strong>（<a href="./../lab/oscilloscope">/lab/oscilloscope</a>）：第 07 章配完 PSC/ARR/CCR 之后，唯一能确认脉宽真的对的办法是把探头挂上去读高电平时间；第 08 章串口波特率、第 09 章 I²C 时序，同样离不开它。</li><li><strong>直流电机驱动</strong>（<a href="./../topics/motor-drive">/topics/motor-drive</a>）：第 07 章 PWM 与第 10 章 ADC + DMA 在这里合流——H 桥、电流采样、编码器测速、软件闭环，第一次把 MCU 的几条外设同时用到一个感性负载上。</li><li><strong>实验台与安全</strong>（<a href="./../lab/bench">/lab/bench</a>）：开发板被烧、板子一上电就发烫，多半是接法与限流的问题。动手搭第一个外设之前，先把这一页的排查顺序读一遍。</li></ul><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>想补通信时序基础：<a href="./../digital/flip-flops">数字电路 · 触发器</a></li><li>想做信号调理：<a href="./../analog/signal-processing">模拟电子 · 信号的运算和处理</a></li><li>手上刚好有个舵机：<a href="./13-servo-control">13 · 舵机控制</a></li><li>想知道哪些章节能当教材读：<a href="./../guide/status">内容状态与成熟度</a></li></ul>',16))])}const A=s(g,[["render",p]]);export{m as __pageData,A as default};
